# --- envjoin_attr/server.py ---
import os
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("t")


class Store:
    def __init__(self, path):
        self.path = path

    def save(self, data, tmp):
        if tmp:
            self.path = "/tmp/authgap_scratch"
        Path(self.path).write_text(data)


class Runner:
    def __init__(self, cmd):
        self.cmd = cmd

    def run(self, safe):
        if safe:
            self.cmd = "ls -l"
        os.system(self.cmd)


class Sink:
    def __init__(self, target):
        self.target = target

    def flush(self, items, data):
        for _it in items:
            self.target = "/tmp/authgap_loop"
        Path(self.target).write_text(data)


class Cfg:
    def __init__(self):
        self.mode = "w"


CFG = Cfg()


@mcp.tool(annotations={"destructiveHint": False})
def save_tool(path: str, data: str, tmp: bool) -> str:
    s = Store(path)
    s.save(data, tmp)
    return "ok"


@mcp.tool(annotations={"readOnlyHint": True})
def run_tool(cmd: str, safe: bool) -> str:
    r = Runner(cmd)
    r.run(safe)
    return "ok"


@mcp.tool(annotations={"destructiveHint": False})
def loop_tool(target: str, items: list, data: str) -> str:
    k = Sink(target)
    k.flush(items, data)
    return "ok"


@mcp.tool(annotations={"destructiveHint": False})
def open_tool(path: str, text: str, append: bool) -> str:
    if append:
        CFG.mode = "a"
    with open(path, CFG.mode) as fh:
        fh.write(text)
    return "ok"

