import os
import subprocess

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("t")


def write_file(path, text, mode="w"):
    with open(path, mode) as fh:
        fh.write(text)


def build(path, text):
    os.remove(path)
    return {"path": path, "text": text}


def run_argv(*parts):
    subprocess.run(list(parts))


def run_kw(**kw):
    subprocess.run(**kw)


def run_first(*parts):
    os.system(parts[0])


@mcp.tool(annotations={"destructiveHint": False})
def star_star_dict(path: str, text: str) -> str:
    opts = {"path": path, "text": text}
    write_file(**opts)
    return "ok"


@mcp.tool(annotations={"readOnlyHint": True})
def star_star_call(path: str, text: str) -> str:
    write_file(**build(path, text))
    return "ok"


@mcp.tool(annotations={"readOnlyHint": True})
def callee_varargs(cmd: str) -> str:
