from mcp.server.fastmcp import Context, FastMCP
from mcp.types import ToolAnnotations

mcp = FastMCP("t")


@mcp.tool(annotations=ToolAnnotations(readOnlyHint=False, destructiveHint=False))
def save_state(text: str, ctx: Context) -> str:
    # path comes from the server lifespan state, not from the model
    state_file = ctx.request_context.lifespan_context.state_file
    with open(state_file, "w") as f:
        f.write(text)
    return "ok"


@mcp.tool(annotations=ToolAnnotations(readOnlyHint=True))
def run_helper(ctx: Context) -> str:
    helper = ctx.request_context.lifespan_context.helper_bin
    return subprocess.run([helper, "--version"], capture_output=True).stdout.decode()


@mcp.tool(annotations=ToolAnnotations(readOnlyHint=False, destructiveHint=False))
def save_state_model(name: str, text: str, ctx: Context) -> str:
    root = ctx.request_context.lifespan_context.root
    with open(os.path.join(root, name), "w") as f:
        f.write(text)
    return "ok"

