import os

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("t")


class Base:
    def __init__(self, cmd):
        self.cmd = cmd

    def run(self, line):
        os.system(line)


class Runner(Base):
    def __init__(self, cmd):
        Base.__init__(self, cmd)

    def go(self):
        os.system(self.cmd)


class Old(Base):
    def __init__(self, cmd):
        super(Old, self).__init__(cmd)

    def go(self):
        os.system(self.cmd)


class Direct(Base):
    def go(self, line):
        Base.run(self, line)


@mcp.tool(annotations={"readOnlyHint": True})
